import{_ as p,a0 as m,w as d,s as n,ao as i,I as s,x as e,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何在Fedora或CentOS上使用Samba共享文件夾 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Fedora或CentOS上使用Samba共享文件夾 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Fedora或CentOS上使用Samba共享文件夾 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Fedora或CentOS上使用Samba共享文件夾 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150318 How to share a directory with Samba on Fedora or CentOS","title":"如何在Fedora或CentOS上使用Samba共享文件夾","tag":"201505","desc":""},"relativePath":"201505/20150318 How to share a directory with Samba on Fedora or CentOS.md","filePath":"[post].md"}'),b={name:"201505/20150318 How to share a directory with Samba on Fedora or CentOS.md"};function l(c,a,S,u,h,f){const t=m("Link");return d(),n("div",null,[a[13]||(a[13]=i(`<h1 id="如何在fedora或centos上使用samba共享文件夾" tabindex="-1">如何在Fedora或CentOS上使用Samba共享文件夾 <a class="header-anchor" href="#如何在fedora或centos上使用samba共享文件夾" aria-label="Permalink to “如何在Fedora或CentOS上使用Samba共享文件夾”">​</a></h1><p>如今，無論在家裏或者是辦公場所，不同的電腦之間共享文件夾已不是什麼新鮮事了。在這種趨勢下，現代操作系統通過網絡文件系統的方式使得電腦間數據的交換變得簡單而透明。如果您工作的環境中既有微軟的Windows又有Linux，那麼，一個共享文件及目錄的方式便是通過一個跨平台網絡文件共享協議：SMB/CIFS。Windows原生的支持SMB/CIFS，Linux也通過開源的軟件Samba實現了SMB/CIFS協議。</p><p>在這篇文章中，我們將展示<strong>如何使用Samba共享文件夾</strong>。我們使用的Linux平台是<strong>Fedora或CentOS</strong>。這篇文章分為四部分。首先，我們在Fedora/CentOS環境下安裝Sambe。接着，我們討論如何調整SELinux和防火牆配置以允許Samba的文件共享。最後我們介紹如何使用Samba來共享文件夾。</p><h3 id="步驟1-在fedora和centos上安裝samba" tabindex="-1">步驟1：在Fedora和CentOS上安裝Samba <a class="header-anchor" href="#步驟1-在fedora和centos上安裝samba" aria-label="Permalink to “步驟1：在Fedora和CentOS上安裝Samba”">​</a></h3><p>首先，安裝Samba以及進行一些基本的配置。</p><p>檢驗Samba是否已經安裝在您的系統中：</p><pre><code>$ rpm -q samba samba-common samba-client 
</code></pre><p>如果上面的命令沒有任何輸出，這意味着Samba並未安裝。這時，應使用下面的命令來安裝Samba。</p><pre><code>$ sudo yum install samba samba-common samba-client 
</code></pre><p>接下來，創建一個用於在網絡中共享的本地文件夾。這個文件夾應該以Samba共享的方式導出到遠程的用户。在這個指南中，我們會在頂層文件夾&#39;/&#39;中創建這個文件夾，因此，請確保您有相應的權限。</p><pre><code>$ sudo mkdir /shared 
</code></pre><p>如果您想在您的home文件夾內創建共享文件夾（例如，~/shared），您必須激活SELinux中Samba的home文件夾共享選項，具體將在後面提到。</p><p>在創建/shared文件夾後，設置文件夾權限以保證其餘用户可以訪問它。</p><pre><code>$ sudo chmod o+rw /shared 
</code></pre><p>如果您不想其他用户對該文件夾擁有寫權限，您需要移除命令中的&#39;w&#39;選項。</p><pre><code>$ sudo chmod o+r /shared 
</code></pre><p>接下來，創建一個空文件來測試。這個文件可以被用來驗證Samba的共享已經被掛載。</p><pre><code>$ sudo touch /shared/file1 
</code></pre><h3 id="步驟2-為samba配置selinux" tabindex="-1">步驟2：為Samba配置SELinux <a class="header-anchor" href="#步驟2-為samba配置selinux" aria-label="Permalink to “步驟2：為Samba配置SELinux”">​</a></h3><p>接下來，我們需要再次配置SELinux。在Fedora和CentOS發行版中SELinux是默認開啓的。SELinux僅在正確的安全配置下才允許Samba讀取和修改文件或文件夾。（例如，加上&#39;samba_share_t&#39;屬性標籤）。</p><p>下面的命令為文件的配置添加必要的標籤：</p><pre><code>$ sudo semanage fcontext -a -t samba_share_t &quot;&lt;directory&gt;(/.*)?&quot; 
</code></pre><p>將<code>&lt;directory&gt;</code>替換為我們之前為Samba共享創建的本地文件夾（例如，/shared）：</p><pre><code>$ sudo semanage fcontext -a -t samba_share_t &quot;/shared(/.*)?&quot; 
</code></pre><p>我們必須執行restorecon命令來激活修改的標籤，命令如下：</p><pre><code>$ sudo restorecon -R -v /shared 
</code></pre><p><img src="https://farm9.staticflickr.com/8584/16652774078_2055f45f70_b.jpg" alt=""></p><p>為了通過Samba共享在我們home文件夾內的文件夾，我們必須在SELinux中開啓共享home文件夾的選項，該選項默認被關閉。下面的命令能達到該效果。如果您並未共享您的home文件夾，那麼您可以跳過該步驟。</p><pre><code>$ sudo setsebool -P samba_enable_home_dirs 1 
</code></pre><h3 id="步驟3-為samba配置防火牆" tabindex="-1">步驟3：為Samba配置防火牆 <a class="header-anchor" href="#步驟3-為samba配置防火牆" aria-label="Permalink to “步驟3：為Samba配置防火牆”">​</a></h3><p>下面的命令用來打開防火牆中Samba共享所需的TCP/UDP端口。</p><p>如果您在使用firewalld（例如，在Fedora和CentOS7下），接下來的命令將會永久的修改Samba相關的防火牆規則。</p><pre><code>$ sudo firewall-cmd --permanent --add-service=samba 
</code></pre><p>如果您在防火牆中使用iptables（例如，CentOS6或者更早的版本），可以使用下面的命令來打開Samba必要的向外的端口。</p><pre><code>$ sudo vi /etc/sysconfig/iptables 
</code></pre><hr><pre><code>-A RH-Firewall-1-INPUT -m state --state NEW -m tcp -p tcp --dport 445 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m udp -p udp --dport 445 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m udp -p udp --dport 137 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m udp -p udp --dport 138 -j ACCEPT
-A RH-Firewall-1-INPUT -m state --state NEW -m tcp -p tcp --dport 139 -j ACCEPT
</code></pre><p>然後重啓iptables服務：</p><pre><code>$ sudo service iptables restart 
</code></pre><h3 id="步驟4-更改samba配置" tabindex="-1">步驟4：更改Samba配置 <a class="header-anchor" href="#步驟4-更改samba配置" aria-label="Permalink to “步驟4：更改Samba配置”">​</a></h3><p>後面的步驟用來配置Samba以將本地文件夾導出為Samba共享文件夾。</p><p>使用文件編輯器打開Samba配置文件，並將下面的行添加到文件的末尾。</p><pre><code>$ sudo nano /etc/samba/smb.conf 
</code></pre><hr><pre><code>[myshare]
comment=my shared files
path=/shared
public=yes
writeable=yes
</code></pre><p>上面在括號內的文本（例如，&quot;myshare&quot;）是Samba共享的資源的名字，它被用來從遠程主機存取Samba共享。</p><p>創建Samba用户帳户，這是掛載和導出Samba文件系統所必須的。我們可以使用smbpasswd工具來創建一個Samba用户。注意，Samba用户帳户必須是已有的Linux用户。如果您嘗試使用smbpasswd添加一個不存在的用户，它會返回一個錯誤的消息。</p><p>如果您不想使用任何已存在的Linux用户作為Samba用户，您可以在您的系統中創建一個新的用户。為安全起見，設置新用户的登錄腳本為/sbin/nologin，並且不創建該用户的home文件夾。</p><p>在這個例子中，我們創建了一個名叫&quot;sambaguest&quot;的用户，如下：</p><pre><code>$ sudo useradd -M -s /sbin/nologin sambaguest
$ sudo passwd sambaguest 
</code></pre><p><img src="https://farm9.staticflickr.com/8702/16814479366_53f540d3ba_b.jpg" alt=""></p><p>在創建一個新用户後，使用smbpasswd命令添加Samba用户。當這個命令詢問一個密碼時，您可以鍵入一個與其用户密碼不同的密碼。</p><pre><code>$ sudo smbpasswd -a sambaguest
</code></pre><p>激活Samba服務，並檢測Samba服務是否在運行。</p><pre><code>$ sudo systemctl enable smb.service
$ sudo systemctl start smb.service
$ sudo systemctl is-active smb 
</code></pre><p><img src="https://farm8.staticflickr.com/7607/16652984770_622f24bccc_b.jpg" alt=""></p><p>使用下面的命令來查看Samba中共享的文件夾列表。</p><pre><code>$ smbclient -U sambaguest -L localhost 
</code></pre><p><img src="https://farm8.staticflickr.com/7281/16220411103_06bf585901_b.jpg" alt=""></p><p>接下來是在Thunar文件管理器中訪問Samba共享文件夾以及對file1進行拷貝複製的截圖。注意，Samba的共享內容可以通過在Thunar中通過 <code>smb://&lt;samba-server-IP-address&gt;/myshare</code> 這個地址來訪問。</p><p><img src="https://farm8.staticflickr.com/7644/16218011174_c8b34fcedc_b.jpg" alt=""></p><hr>`,62)),s("p",null,[a[1]||(a[1]=e("via: ",-1)),o(t,{href:"http://xmodulo.com/share-directory-samba-fedora-centos.html"},{default:r(()=>[...a[0]||(a[0]=[e("http://xmodulo.com/share-directory-samba-fedora-centos.html",-1)])]),_:1})]),s("p",null,[a[5]||(a[5]=e("作者：",-1)),o(t,{href:"http://xmodulo.com/author/kristophorus"},{default:r(()=>[...a[2]||(a[2]=[e("Kristophorus Hadiono",-1)])]),_:1}),a[6]||(a[6]=e(" 譯者：",-1)),o(t,{href:"https://github.com/wwy-hust"},{default:r(()=>[...a[3]||(a[3]=[e("wwy-hust",-1)])]),_:1}),a[7]||(a[7]=e(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:r(()=>[...a[4]||(a[4]=[e("wxy",-1)])]),_:1})]),s("p",null,[a[10]||(a[10]=e("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...a[8]||(a[8]=[e("LCTT",-1)])]),_:1}),a[11]||(a[11]=e(" 原創翻譯，",-1)),o(t,{href:"http://linux.cn/"},{default:r(()=>[...a[9]||(a[9]=[e("Linux中國",-1)])]),_:1}),a[12]||(a[12]=e(" 榮譽推出",-1))])])}const g=p(b,[["render",l]]);export{T as __pageData,g as default};
